// @ts-check

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

import {docSections} from './docsSections.mjs';

/**
 * One sidebar per top-level subject folder (docs/01-core-java → coreJavaSidebar … ),
 * each autogenerated from that folder. Each one is shown as its own navbar tab
 * (see docusaurus.config.js → navbar.items). docs/intro.md is the landing page and
 * belongs to no sidebar.

 @type {import('@docusaurus/plugin-content-docs').SidebarsConfig}
 */
const sidebars = Object.fromEntries(
  docSections().map(({dir, sidebarId}) => [sidebarId, [{type: 'autogenerated', dirName: dir}]]),
);

export default sidebars;
